   <soap:Body>
      <GetPostageLabelResponse xmlns="www.envmgr.com/LabelService">
         <LabelRequestResponse>
            <Status>0</Status>
            <Base64LabelImage></Base64LabelImage>
            <PIC>9400150206210040269616</PIC>
            <TrackingNumber>9400150206210040269616</TrackingNumber>
            <FinalPostage>4.51</FinalPostage>
            <TransactionID>429867</TransactionID>
            <TransactionDateTime>20250601102100</TransactionDateTime>
            <PostmarkDate>20250601</PostmarkDate>
            <PostageBalance>441.8500</PostageBalance>
            <CostCenter>0</CostCenter>
            <RequesterID>iweb</RequesterID>
            <ReferenceID2/>
            <ReferenceID3/>
            <ReferenceID4/>
            <SDRValue/>
            <FormURL/>
            <LabelCategory/>
         </LabelRequestResponse>
      </GetPostageLabelResponse>
   </soap:Body>
</soap:Envelope>';
        $service->parseSoapResponse($stringResponse, $order);
    }
}
